import { ScrollView, View } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { HeaderBar } from '@/components'
import { SettingsItem } from '../../components/primitives/SettingsItem'
import { router } from 'expo-router'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { useState } from 'react'

export const NotificationsScreen = () => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()

	const [emailUpdates, setEmailUpdates] = useState(true)
	const [newFeatures, setNewFeatures] = useState(true)
	const [appActivity, setAppActivity] = useState(true)
	const [lowCredits, setLowCredits] = useState(true)

	const onClose = () => {
		router.back()
	}

	const handleSystemsSettings = () => {}

	return (
		<ScrollView
			style={styles.scrollView(theme)}
			showsVerticalScrollIndicator={false}
			contentContainerStyle={{
				paddingTop: insets.top,
				paddingBottom: insets.bottom + 16,
				gap: 32
			}}
		>
			<HeaderBar title="Notifications" onClose={onClose} showBackButton />

			<View style={styles.section}>
				<SettingsItem
					title="Email updates"
					type="toggle"
					toggleValue={emailUpdates}
					onToggleChange={setEmailUpdates}
					appearance="primary"
				/>

				<SettingsItem
					title="New features"
					type="toggle"
					toggleValue={newFeatures}
					onToggleChange={setNewFeatures}
					appearance="primary"
				/>

				<SettingsItem
					title="App activity"
					type="toggle"
					toggleValue={appActivity}
					onToggleChange={setAppActivity}
					appearance="primary"
				/>

				<SettingsItem
					title="Low credits"
					type="toggle"
					toggleValue={lowCredits}
					onToggleChange={setLowCredits}
					appearance="primary"
				/>

				<SettingsItem
					title="Systems settings"
					type="link"
					onPress={handleSystemsSettings}
					appearance="primary"
				/>
			</View>
		</ScrollView>
	)
}

const styles = defineStyles({
	scrollView: (theme: Theme) => ({
		backgroundColor: colors[theme].background,
		paddingHorizontal: 24
	}),
	section: {
		gap: 28
	}
})
